insert into public.course_modules (id, course_id, title, description, position) values
  ('f5ac9d3d-6d3f-58fa-05d2-15f9a5ebbf65', 'c9468857-0122-856c-b60f-5c05e13778a7', 'Adresser et segmenter', 'Lire une adresse IPv4, la masquer et découper un réseau en sous-réseaux.', 3),
  ('164a6fca-6567-1fd3-2956-fe662b74b303', 'c9468857-0122-856c-b60f-5c05e13778a7', 'Lire un échange TCP', 'Suivre une connexion TCP, comprendre les ports et retrouver une adresse avec DNS et ARP.', 4),
