insert into public.labs (id, slug, title, description, category, difficulty, xp_reward, objectives, hints, terminal_lines, position, course_id, format, briefing, constraints, tools, requires_computer, is_assessment, estimated_minutes) values
  ('c1c18636-1360-98fb-338b-1ae63b3a0fc2', 'reseau-instable', 'Réseau instable : lire une capture', 'Un collègue signale que l’intranet répond par intermittence. Il te fournit une capture : retrouve qui parle, qui refuse et qui reste muet.', 'reseau', 'debutant', 120, array['Identifier le poste qui a généré le trafic', 'Associer une adresse IP à une adresse MAC avec ARP', 'Suivre une résolution DNS puis un handshake TCP', 'Distinguer un port fermé d’un hôte silencieux']::text[], array['Les premiers paquets de la capture sont ARP, puis DNS.', 'RST-ACK signifie que le port est fermé. Un SYN répété sans réponse est autre chose.', 'Compte les lignes SYN envoyées vers l’hôte silencieux, retransmissions comprises.']::text[], '{}'::text[], 100, 'c9468857-0122-856c-b60f-5c05e13778a7', 'pcap', 'Un utilisateur se plaint que l’intranet est lent et que deux services internes ne répondent pas. Le service informatique a capturé le trafic de son poste pendant quelques secondes. Ta mission : analyser cette capture pour comprendre ce qui fonctionne (nom, adresse, page web) et ce qui échoue (un port refusé, un hôte qui ne répond jamais).', array['Analyse uniquement le fichier fourni : ne scanne aucun réseau réel.', 'Relis les paquets dans l’ordre chronologique avant de répondre.']::text[], array['Visionneuse de capture CyberPingo', 'Wireshark (facultatif)', 'tcpdump (facultatif)']::text[], false, false, 25),
  ('9ee6df7f-4307-0907-4f59-56399b408e55', 'incident-pare-feu', 'Incident au pare-feu : lire un journal', 'Le pare-feu a enregistré une série de refus suivie d’une autorisation suspecte. Retrouve l’attaquant, ce qu’il visait et comment il est passé.', 'reseau', 'intermediaire', 150, array['Trouver la source la plus agressive', 'Identifier le service visé', 'Repérer le moment où une règle laisse passer l’attaquant', 'Nommer la règle fautive']::text[], array['Filtre sur DENY, puis compte par adresse source.', 'Une même source peut viser plusieurs ports : prends celui qui revient le plus.', 'Cherche la première ligne ALLOW de l’attaquant vers le serveur.']::text[], '{}'::text[], 110, 'c9468857-0122-856c-b60f-5c05e13778a7', 'logs', 'Le journal du pare-feu FW01 contient six minutes de trafic autour du serveur interne 192.168.10.50. Une adresse externe semble avoir insisté sur plusieurs services avant qu’une règle ne la laisse passer. Ta mission : reconstituer l’incident à partir des lignes du journal et nommer la règle qui a ouvert la porte.', array['Ne conclus que ce que le journal prouve : cite les lignes qui appuient ta réponse.', 'Les heures sont en UTC.']::text[], array['Visionneuse de journaux CyberPingo', 'grep, sort et uniq (facultatif)', 'Un tableur (facultatif)']::text[], false, false, 30),
  ('6450089f-a279-e254-e1ec-0b91edec230a', 'packet-tracer-sous-reseaux', 'Packet Tracer : le plan d’adressage de l’atelier Kora', 'Découpe 192.168.20.0/24 en quatre sous-réseaux pour une petite entreprise, puis construis et teste le réseau dans Packet Tracer.', 'reseau', 'intermediaire', 200, array['Calculer un plan d’adressage en CIDR', 'Configurer les interfaces d’un routeur', 'Tester la connectivité entre sous-réseaux', 'Documenter son travail dans un rapport']::text[], array['Pour quatre sous-réseaux égaux dans un /24, ajoute deux bits au masque.', 'Les sous-réseaux commencent à des multiples de la taille du bloc.', 'Le résumé des interfaces s’affiche avec une commande show.']::text[], '{}'::text[], 120, 'c9468857-0122-856c-b60f-5c05e13778a7', 'packet_tracer', 'L’atelier Kora est une petite entreprise qui dispose du réseau 192.168.20.0/24. Elle veut quatre sous-réseaux de taille identique : Direction, Atelier, Comptabilité et Invités, pour que les invités n’atteignent jamais la comptabilité. Chaque sous-réseau reçoit un routeur R1 comme passerelle, qui prend la première adresse utilisable du sous-réseau. Ta mission : calculer le plan d’adressage, le monter dans Packet Tracer (ou à la main) et déposer un rapport si tu veux un retour d’un formateur.', array['Utilise la même taille pour les quatre sous-réseaux.', 'La passerelle de chaque sous-réseau prend sa première adresse utilisable.', 'Packet Tracer est facultatif : les calculs se valident ici, sans lui.']::text[], array['Cisco Packet Tracer (gratuit, sur ton ordinateur)', 'Un outil de calcul de sous-réseaux ou Python (module ipaddress)']::text[], true, false, 60),
  ('57d59a46-5481-7f2d-8da4-3e2d19ea0f3b', 'evaluation-reseaux', 'Évaluation réseau : enquête sur un scan interne', 'Une machine du réseau sonde ton serveur. Prouve que tu sais lire la capture, repérer le scan et situer les machines dans leurs sous-réseaux.', 'reseau', 'intermediaire', 300, array['Distinguer le trafic normal d’un scan', 'Mesurer l’étendue du scan', 'Lister les services ouverts découverts', 'Situer deux machines par rapport à un masque /26']::text[], array['Le client normal commence par une résolution DNS. Le scanner n’en fait aucune.', 'Compte les ports différents ciblés par la même source.', 'Un port ouvert répond SYN-ACK, un port fermé répond RST-ACK.']::text[], '{}'::text[], 130, 'c9468857-0122-856c-b60f-5c05e13778a7', 'pcap', 'Une alerte signale du trafic anormal vers le serveur 192.168.10.50. Une capture de quelques secondes est disponible. Ta mission : identifier la machine qui sonde le serveur, lister ce qu’elle a découvert et déterminer si elle se trouve dans le même sous-réseau que le serveur. Ce laboratoire valide les compétences du parcours Réseaux : sans indice, il demande de mobiliser les adresses, TCP, DNS et l’analyse de capture.', array['Évaluation : réponds sans aide extérieure, comme en situation réelle.', 'Appuie chaque réponse sur la capture, pas sur une supposition.']::text[], array['Visionneuse de capture CyberPingo', 'Wireshark (facultatif)', 'Une calculatrice de sous-réseaux (facultatif)']::text[], false, true, 45)
insert into public.lab_tasks (id, lab_id, position, prompt, hint, answer_format) values
  ('826ed277-61b8-e6b0-180d-acc0020aa47a', 'c1c18636-1360-98fb-338b-1ae63b3a0fc2', 1, 'Quelle est l’adresse IP du poste du client, celui qui envoie la requête ARP et la requête DNS ?', 'C’est la source du premier paquet.', 'Adresse IPv4, par exemple 10.0.0.1'),
  ('99e25b1d-68ff-2e91-bdeb-d4eb259c05d9', 'c1c18636-1360-98fb-338b-1ae63b3a0fc2', 2, 'Quelle est l’adresse MAC qui répond à la requête ARP pour 192.168.10.2 ?', 'Lis le paquet ARP qui suit la requête.', 'Six octets hexadécimaux, par exemple 00:11:22:33:44:55'),
  ('1f7353e2-5fd8-3e7a-f31c-d89bbf5f4985', 'c1c18636-1360-98fb-338b-1ae63b3a0fc2', 3, 'Quelle adresse IP la réponse DNS donne-t-elle pour intranet.cyberpingo.lab ?', 'Ouvre la réponse DNS (enregistrement A).', 'Adresse IPv4'),
  ('726c5bc1-78e7-edc1-142a-67997a76c7b9', 'c1c18636-1360-98fb-338b-1ae63b3a0fc2', 4, 'Un SYN vers le port suivant reçoit immédiatement un RST-ACK : quel est ce port ?', 'Cherche les paquets RST. Le port est celui visé par le SYN.', 'Numéro de port'),
  ('13be0015-13f3-d8a8-5e2c-d8442e409c69', 'c1c18636-1360-98fb-338b-1ae63b3a0fc2', 5, 'Quelle adresse IP ne répond jamais aux SYN du client ?', 'Cherche une destination qui n’apparaît jamais comme source.', 'Adresse IPv4'),
  ('0fa73d09-7cb5-e437-06ef-24264b090384', 'c1c18636-1360-98fb-338b-1ae63b3a0fc2', 6, 'Combien de paquets SYN le client envoie-t-il vers cette adresse, retransmissions comprises ?', 'Le même SYN est renvoyé à intervalles croissants.', 'Un nombre entier'),
  ('5883d0b7-5f7c-cd36-3556-6dc412464069', '9ee6df7f-4307-0907-4f59-56399b408e55', 1, 'Quelle adresse IP source cumule le plus de lignes DENY ?', 'Filtre sur DENY puis regarde les sources.', 'Adresse IPv4'),
  ('fb2c5d48-1545-2017-7241-11ebb1427396', '9ee6df7f-4307-0907-4f59-56399b408e55', 2, 'Quel est le port de destination le plus visé par cette adresse ?', 'Regarde le champ dst= des lignes de cette source.', 'Numéro de port'),
  ('f62e456a-a4d7-6907-9d75-0edef8a245b0', '9ee6df7f-4307-0907-4f59-56399b408e55', 3, 'Combien de lignes DENY cette adresse a-t-elle au total, tous ports confondus ?', 'Compte les DENY de cette source uniquement.', 'Un nombre entier'),
  ('bb67d078-cf85-d6f7-5382-b15352a2901f', '9ee6df7f-4307-0907-4f59-56399b408e55', 4, 'À quelle heure (UTC, format HH:MM:SS) le pare-feu laisse-t-il passer cette adresse pour la première fois ?', 'Cherche la première ligne ALLOW dont la source est l’attaquant.', 'HH:MM:SS'),
  ('1bc268ba-d00c-552e-ea3b-5dcd081d4779', '9ee6df7f-4307-0907-4f59-56399b408e55', 5, 'Quel est le nom de la règle qui l’autorise ?', 'Le nom suit rule= sur la ligne ALLOW.', 'Nom de la règle'),
  ('e1fe66dc-dd73-3aff-c12a-b020fa83d60d', '6450089f-a279-e254-e1ec-0b91edec230a', 1, 'Quel masque de sous-réseau (notation décimale pointée) obtiens-tu pour quatre sous-réseaux égaux dans un /24 ?', 'Un /24 avec deux bits de plus devient un /26.', 'Masque, par exemple 255.255.255.0'),
  ('4b211fc9-d344-ee91-ccc1-8f08eef00470', '6450089f-a279-e254-e1ec-0b91edec230a', 2, 'Quelle est l’adresse réseau du sous-réseau « Atelier » (le deuxième) ?', 'Les blocs commencent à 0, puis la taille du bloc, puis le double...', 'Adresse IPv4'),
  ('a2224252-5227-4569-3a42-4fe2677f9f15', '6450089f-a279-e254-e1ec-0b91edec230a', 3, 'Quelle est la première adresse utilisable du sous-réseau « Comptabilité » ?', 'C’est l’adresse réseau plus un.', 'Adresse IPv4'),
  ('81158b7b-4b11-ef28-0d51-d2c6e986806b', '6450089f-a279-e254-e1ec-0b91edec230a', 4, 'Quelle est l’adresse de diffusion du sous-réseau « Invités » ?', 'C’est la dernière adresse du bloc.', 'Adresse IPv4'),
  ('80121445-15e2-0d2d-29f2-bf560568c118', '6450089f-a279-e254-e1ec-0b91edec230a', 5, 'Combien de machines peut-on adresser dans chaque sous-réseau ?', 'Taille du bloc moins deux.', 'Un nombre entier'),
  ('b91a8b10-1500-47e1-f80c-84354635243e', '6450089f-a279-e254-e1ec-0b91edec230a', 6, 'Quelle adresse IP donnes-tu à l’interface de R1 dans le sous-réseau « Atelier » ?', 'La passerelle prend la première adresse utilisable.', 'Adresse IPv4'),
  ('b907d4d6-335b-7a29-87ac-016b04bdef7e', '6450089f-a279-e254-e1ec-0b91edec230a', 7, 'Quelle commande du routeur affiche une ligne par interface avec son adresse IP et son état ?', 'Commence par show ip... et termine par brief.', 'Commande IOS'),
  ('3c3c24d2-9c4c-1350-54fa-48744aa04828', '57d59a46-5481-7f2d-8da4-3e2d19ea0f3b', 1, 'Quelle adresse IP sonde le serveur (envoie des SYN vers de nombreux ports) ?', 'Cherche la source qui envoie le plus de SYN vers des ports différents.', 'Adresse IPv4'),
  ('d842216c-6741-7942-a499-b18f049cc592', '57d59a46-5481-7f2d-8da4-3e2d19ea0f3b', 2, 'Combien de ports différents le scanner a-t-il sondés ?', 'Compte les ports de destination distincts.', 'Un nombre entier'),
  ('67aef84e-2045-7dd7-d0f8-d15d0cb63f42', '57d59a46-5481-7f2d-8da4-3e2d19ea0f3b', 3, 'Combien de ports ont répondu SYN-ACK (ports ouverts) ?', 'Seuls les ports ouverts répondent SYN-ACK.', 'Un nombre entier'),
  ('602ee4d1-c2c5-6a5a-d41c-49178b392ade', '57d59a46-5481-7f2d-8da4-3e2d19ea0f3b', 4, 'Quel port ouvert correspond à une base de données MySQL ?', 'Parmi les ports ouverts, un seul est celui d’un serveur de base de données.', 'Numéro de port'),
  ('06e885ad-6cca-6080-ddc8-e5a7d9a047f4', '57d59a46-5481-7f2d-8da4-3e2d19ea0f3b', 5, 'Quels drapeaux TCP le serveur renvoie-t-il sur un port ouvert au SYN du scanner ?', 'C’est la deuxième étape du handshake.', 'Par exemple SYN-ACK'),
  ('946ca68f-a9bd-474e-af00-7ff9d756e6d8', '57d59a46-5481-7f2d-8da4-3e2d19ea0f3b', 6, 'Quel drapeau le scanner envoie-t-il après un SYN-ACK pour ne pas établir la connexion ?', 'Il referme brutalement.', 'Un drapeau TCP'),
  ('d95b455f-9360-00a0-4781-7a8dfdc8119d', '57d59a46-5481-7f2d-8da4-3e2d19ea0f3b', 7, 'Quelle adresse IP la réponse DNS donne-t-elle pour portail.cyberpingo.lab ?', 'Regarde la réponse du client normal.', 'Adresse IPv4'),
  ('7780bf05-8320-3c82-b8cf-44331b2c3489', '57d59a46-5481-7f2d-8da4-3e2d19ea0f3b', 8, 'Avec un masque /26, quelle est l’adresse réseau du serveur 192.168.10.50 ?', 'Les blocs d’un /26 font 64 adresses.', 'Adresse IPv4'),
  ('f58ddfc2-6ca4-df36-4045-a581654a56d4', '57d59a46-5481-7f2d-8da4-3e2d19ea0f3b', 9, 'Avec un masque /26, le scanner 192.168.10.99 est-il dans le même sous-réseau que le serveur ? (oui ou non)', 'Compare les blocs des deux machines.', 'oui ou non'),
  ('a82cd7c1-2ae4-834a-dca7-552294aaba1a', '57d59a46-5481-7f2d-8da4-3e2d19ea0f3b', 10, 'Quelle est l’adresse de diffusion du sous-réseau /26 du scanner ?', 'C’est la dernière adresse de son bloc.', 'Adresse IPv4')
insert into private.lab_task_keys (task_id, accepted, explanation) values
  ('826ed277-61b8-e6b0-180d-acc0020aa47a', array['192.168.10.23']::text[], 'Le client est 192.168.10.23 : c’est lui qui diffuse la requête ARP puis interroge le DNS.'),
  ('99e25b1d-68ff-2e91-bdeb-d4eb259c05d9', array['00:1b:21:aa:00:02', '00-1b-21-aa-00-02']::text[], 'ARP associe 192.168.10.2 à l’adresse MAC 00:1b:21:aa:00:02.'),
  ('1f7353e2-5fd8-3e7a-f31c-d89bbf5f4985', array['192.168.10.50']::text[], 'Le serveur DNS répond 192.168.10.50. C’est vers cette adresse que le client ouvre ensuite sa connexion HTTP.'),
  ('726c5bc1-78e7-edc1-142a-67997a76c7b9', array['8080']::text[], 'Le port 8080 est fermé : la machine répond RST-ACK. Elle est joignable, mais aucun service n’écoute.'),
  ('13be0015-13f3-d8a8-5e2c-d8442e409c69', array['192.168.10.70']::text[], '192.168.10.70 ne répond pas du tout. L’absence totale de réponse évoque un filtrage par pare-feu ou un hôte injoignable, pas un port fermé.'),
  ('0fa73d09-7cb5-e437-06ef-24264b090384', array['4']::text[], 'Le client envoie 4 SYN : l’original et trois retransmissions espacées de plus en plus. Sans réponse, TCP finit par abandonner.'),
  ('5883d0b7-5f7c-cd36-3556-6dc412464069', array['198.51.100.77']::text[], '198.51.100.77 cumule 27 refus, bien plus que les autres sources. C’est le principal suspect.'),
  ('fb2c5d48-1545-2017-7241-11ebb1427396', array['22']::text[], 'Le port 22 (SSH) est visé en rafale : c’est typique d’une tentative d’accès à distance par force brute.'),
  ('f62e456a-a4d7-6907-9d75-0edef8a245b0', array['27']::text[], 'Il y a 27 refus. L’essentiel vise le port 22, avec quelques tentatives sur le Bureau à distance.'),
  ('bb67d078-cf85-d6f7-5382-b15352a2901f', array['09:14:12', '09:14:12z']::text[], 'Le premier ALLOW est à 09:14:12. Après une longue série de refus, une règle finit par autoriser la même source.'),
  ('1bc268ba-d00c-552e-ea3b-5dcd081d4779', array['allow-admin-tmp']::text[], 'La règle ALLOW-ADMIN-TMP est temporaire et trop permissive : elle laisse l’attaquant atteindre le service SSH. À supprimer et à contrôler.'),
  ('e1fe66dc-dd73-3aff-c12a-b020fa83d60d', array['255.255.255.192']::text[], 'Il faut deux bits de plus : /26, soit 255.255.255.192. Chaque sous-réseau compte 64 adresses.'),
  ('4b211fc9-d344-ee91-ccc1-8f08eef00470', array['192.168.20.64']::text[], 'Le deuxième bloc commence à 192.168.20.64 : 192.168.20.0 + 64.'),
  ('a2224252-5227-4569-3a42-4fe2677f9f15', array['192.168.20.129']::text[], 'Le réseau Comptabilité est 192.168.20.128. Sa première adresse utilisable est 192.168.20.129.'),
  ('81158b7b-4b11-ef28-0d51-d2c6e986806b', array['192.168.20.255']::text[], 'Le bloc Invités va de 192.168.20.192 à 192.168.20.255. La dernière adresse est celle de diffusion.'),
  ('80121445-15e2-0d2d-29f2-bf560568c118', array['62']::text[], 'Un /26 compte 64 adresses, dont deux sont réservées : 62 utilisables.'),
  ('b91a8b10-1500-47e1-f80c-84354635243e', array['192.168.20.65']::text[], 'La passerelle de Atelier est 192.168.20.65, la première adresse utilisable du bloc 192.168.20.64.'),
  ('b907d4d6-335b-7a29-87ac-016b04bdef7e', array['show ip interface brief', 'show ip int brief', 'show ip int br', 'sh ip int br', 'sh ip interface brief']::text[], 'show ip interface brief résume l’adresse et l’état de chaque interface. C’est la commande de vérification la plus utile après une configuration.'),
  ('3c3c24d2-9c4c-1350-54fa-48744aa04828', array['192.168.10.99']::text[], '192.168.10.99 envoie un SYN vers 14 ports différents en quelques dizaines de millisecondes : c’est un scan.'),
  ('d842216c-6741-7942-a499-b18f049cc592', array['14']::text[], 'Le scanner sonde 14 ports : 21, 22, 23, 25, 53, 80, 110, 139, 143, 443, 445, 3306, 3389 et 8080.'),
  ('67aef84e-2045-7dd7-d0f8-d15d0cb63f42', array['4']::text[], '4 ports sont ouverts : 22, 80, 443, 3306. Les autres répondent RST-ACK.'),
  ('602ee4d1-c2c5-6a5a-d41c-49178b392ade', array['3306']::text[], 'Le port 3306 est celui de MySQL. Une base de données ne devrait pas être joignable depuis tout le réseau : c’est une découverte sensible.'),
  ('06e885ad-6cca-6080-ddc8-e5a7d9a047f4', array['syn-ack', 'syn,ack', 'syn/ack', 'syn ack', 'syn+ack', 'syn, ack']::text[], 'Un port ouvert répond SYN-ACK. C’est ce qui révèle au scanner que le service existe.'),
  ('946ca68f-a9bd-474e-af00-7ff9d756e6d8', array['rst', 'reset', 'rst-ack']::text[], 'Le scanner répond RST : il a appris que le port est ouvert sans jamais terminer le handshake, d’où le nom de scan demi-ouvert.'),
  ('d95b455f-9360-00a0-4781-7a8dfdc8119d', array['192.168.10.50']::text[], 'portail.cyberpingo.lab se résout en 192.168.10.50, le serveur visé par le scan. Le client légitime et le scanner ciblent donc la même machine.'),
  ('7780bf05-8320-3c82-b8cf-44331b2c3489', array['192.168.10.0']::text[], '192.168.10.50 est dans le bloc 192.168.10.0 à 192.168.10.63.'),
  ('f58ddfc2-6ca4-df36-4045-a581654a56d4', array['non', 'no']::text[], 'Le scanner est dans le bloc 192.168.10.64 à 192.168.10.127, le serveur dans 192.168.10.0 à 192.168.10.63 : ils sont dans deux sous-réseaux différents.'),
  ('a82cd7c1-2ae4-834a-dca7-552294aaba1a', array['192.168.10.127']::text[], 'Le bloc du scanner va de 192.168.10.64 à 192.168.10.127. Cette dernière adresse est la diffusion.')
insert into public.lab_assets (id, lab_id, kind, title, description, url, position) values
  ('85ee53b3-029f-1504-c6e7-8c7960cdc24d', 'c1c18636-1360-98fb-338b-1ae63b3a0fc2', 'pcap', 'Capture du poste client (reseau-instable.pcap)', '22 paquets : ARP, DNS, une session HTTP, un port refusé et un hôte silencieux.', '/labs/reseau-instable.pcap', 1),
  ('393af39c-bec5-0c7d-b2c0-832c00f9ad07', 'c1c18636-1360-98fb-338b-1ae63b3a0fc2', 'guide', 'Guide : les filtres et drapeaux utiles', 'Les filtres Wireshark et les drapeaux TCP à connaître.', '/labs/guide-wireshark.md', 2),
  ('f03bbc3a-ab86-cf6d-b286-fc191dcd1f14', '9ee6df7f-4307-0907-4f59-56399b408e55', 'log', 'Journal du pare-feu FW01 (incident-pare-feu.log)', '83 lignes sur six minutes : trafic normal, refus répétés, puis une autorisation.', '/labs/incident-pare-feu.log', 1),
  ('c78da72b-96e8-7581-2115-f86139a84346', '6450089f-a279-e254-e1ec-0b91edec230a', 'topology', 'Topologie de l’atelier Kora', 'Un routeur, trois commutateurs et trois PC. Le quatrième sous-réseau est à calculer.', '/labs/packet-tracer-topologie.svg', 1),
  ('e82bf999-67fa-905b-f513-b13d890b1fcf', '6450089f-a279-e254-e1ec-0b91edec230a', 'guide', 'Guide pas à pas Packet Tracer', 'Matériel, plan d’adressage, commandes et test de connectivité.', '/labs/packet-tracer-guide.md', 2),
  ('55b6ce0f-2108-35b8-0079-6b4d5d83b2cc', '6450089f-a279-e254-e1ec-0b91edec230a', 'report_template', 'Modèle de rapport', 'Plan d’adressage, méthode, tests et difficultés à remplir.', '/labs/modele-rapport-reseau.md', 3),
  ('cb4eacf8-3dc1-d37d-c8cd-a984fa923468', '57d59a46-5481-7f2d-8da4-3e2d19ea0f3b', 'pcap', 'Capture du serveur (evaluation-reseaux.pcap)', 'Un client légitime et un scan SYN contre le serveur interne.', '/labs/evaluation-reseaux.pcap', 1),
  ('fbd4b12f-3d7b-5ef7-5ef4-b7dc516130e8', '57d59a46-5481-7f2d-8da4-3e2d19ea0f3b', 'guide', 'Guide : les filtres et drapeaux utiles', 'Les filtres Wireshark et les drapeaux TCP à connaître.', '/labs/guide-wireshark.md', 2)
