insert into public.mascot_lines (id, event, expression, text_fr, priority, position) values
  ('da285d27-f5dc-9470-288b-5239d3b4d73b', 'welcome', 'happy', 'Salut, moi c’est Pingo ! Je t’accompagne dans chaque leçon. On commence quand tu veux.', 5, 10),
  ('d87276bc-32ac-b61e-b061-c611b495e6e5', 'welcome', 'encouraging', 'Content de te revoir ! Une leçon, un exercice, et tu avances déjà.', 4, 20),
  ('199c8897-2797-aff0-de28-71ca23bad1e1', 'lesson_start', 'focused', 'On se concentre : lis les objectifs, ils te disent ce que tu sauras faire à la fin.', 3, 30),
  ('8a6d2c0b-c6af-5861-5ecb-a3e7b19d9457', 'lesson_start', 'explanation', 'Si un schéma te semble obscur, relis-le calmement. Un bon schéma vaut dix paragraphes.', 2, 40),
  ('f81109a2-298b-3425-fd9a-8900724b9882', 'exercise_success', 'proud', 'Bonne réponse ! Tu viens de prouver que tu as compris, pas seulement retenu.', 5, 50),
  ('ff1f8c62-0c3e-8b51-17fb-1aa2e1e0e778', 'exercise_success', 'happy', 'Exact ! Continue sur cette lancée.', 3, 60),
  ('d20265aa-6f59-18a3-fa9c-7efd94751304', 'exercise_fail', 'disappointed', 'Pas tout à fait. Relis l’énoncé, regarde l’indice et retente : se tromper fait partie de l’entraînement.', 5, 70),
  ('fdbce325-8d11-86ed-0c3f-4711db554265', 'exercise_fail', 'thinking', 'Hmm. Ouvre la capture ou le journal et cherche la ligne qui prouve ta réponse.', 3, 80),
  ('4e16390a-9efb-7a07-e19d-c240cab0e2e5', 'chapter_end', 'proud', 'Leçon terminée ! Prends une seconde pour résumer ce que tu viens d’apprendre avec tes mots.', 5, 90),
  ('5ebb2053-f07e-6ea3-bef4-de8e81774703', 'chapter_end', 'happy', 'Une de plus de validée. La régularité bat l’intensité.', 3, 100),
  ('c92bb8fc-2df0-6989-781c-0b77358c1f0b', 'level_up', 'celebration', 'Niveau supérieur ! Chaque niveau est le résultat de vrais efforts. Bravo !', 8, 110),
  ('ef264b05-6e2e-1a7e-0c7d-a43b1bd16255', 'badge', 'celebration', 'Un nouveau badge pour ta collection. Va voir sa condition : tu l’as gagné pour de bon.', 7, 120),
  ('72a62b06-091f-21d3-b2d5-d8de43eaafe2', 'badge', 'surprised', 'Oh, un badge ! Tu ne l’avais pas vu venir ?', 4, 130),
  ('65b23789-9944-a131-fe16-66c717af20fa', 'challenge', 'mission', 'Nouvelle mission : lis le briefing, repère les contraintes et lance-toi.', 6, 140),
  ('1c741aeb-ee97-8044-13ea-300e4588d990', 'challenge', 'focused', 'En situation réelle, personne ne te donne la réponse. Fie-toi aux preuves.', 3, 150),
  ('a8fd2f99-7338-2c44-a64e-efee18234cd9', 'return_after_absence', 'happy', 'Te revoilà ! Pas de souci pour la pause : on reprend doucement là où tu étais.', 6, 160),
  ('cb170032-3907-6241-cf05-f3a6ced1c2c5', 'return_after_absence', 'encouraging', 'Un petit rappel pour se remettre en route : refais le dernier quiz, c’est rapide.', 4, 170),
  ('5a82bf3c-f089-d148-7238-39f21025814a', 'new_skill', 'expert', 'Compétence validée par une vraie mise en pratique. C’est ce qui compte face à un employeur.', 8, 180),
  ('7782fcb9-e6b4-bfd0-b152-fbca1c58b83b', 'rank_up', 'celebration', 'Nouveau rang ! Ton parcours se voit maintenant. Continue, la suite t’attend.', 9, 190),
  ('60a3491a-3849-6fb4-4ab7-710bc689838d', 'path_complete', 'celebration', 'Parcours terminé ! De la théorie à la pratique, tu as bouclé la boucle. Fier de toi.', 10, 200),
  ('f7ca590c-213a-a310-4c5c-b43ab4568a82', 'lab_complete', 'proud', 'Laboratoire réussi ! Tu as fait un vrai travail d’analyste : preuve par preuve.', 7, 210),
  ('77509e8f-4f43-9818-e577-3a9ff2771018', 'lab_complete', 'expert', 'Mission accomplie. Retiens la méthode : observer, formuler une hypothèse, vérifier.', 4, 220)
